          "source_correspondence": "A01, S166-S168"
        },
        {
          "term": "highly evidenced",
          "formal_definition": "HighlyEvidenced E P := E P",
          "reader_meaning": "There is strong evidence for P.",
          "source_correspondence": "A01, A03, S167, S171-S175"
